// Fast sine
static inline float sinFast(float phaseNorm) {
    // Wrap phase to 0.0 - 1.0
    while (phaseNorm >= 1.0f) phaseNorm -= 1.0f;
    while (phaseNorm < 0.0f) phaseNorm += 1.0f;

    // Calc exact index
    float pos = phaseNorm * (float)TRIG_TABLE_SIZE;
    int indexA = (int)pos;
    int indexB = (indexA + 1) & TRIG_TABLE_MASK;
    float frac = pos - (float)indexA;

    // Linear interpolation
    return sinTable[indexA] + (frac * (sinTable[indexB] - sinTable[indexA]));
}

// Fast cosine
static inline float cosFast(float phaseNorm) {
    return sinFast(phaseNorm + 0.25f);
}

// Fast atan
static inline float atanFast(float phaseNorm) {
    // Handle sign
    float input = phaseNorm;
    bool isNegative = false;
    if (input < 0.0f) {
        isNegative = true;
        input = -input;
    }

    // Handle range > 1.0
    bool invert = false;
    if (input > 1.0f) {
        invert = true;
        input = 1.0f / input;
    }

    // Linear interpolation
    float indexFloat = input * (float)TRIG_TABLE_SIZE;
    int32_t indexInt = (int32_t)indexFloat;
    if (indexInt >= (TRIG_TABLE_SIZE - 1)) indexInt = TRIG_TABLE_SIZE - 2;
    float frac = indexFloat - (float)indexInt;
    float y1 = atanTable[indexInt];
    float y2 = atanTable[indexInt + 1];
    float result = y1 + (frac * (y2 - y1));

    // Inversion
    if (invert) {
        // atan(x) = PI/2 - atan(1/x)
        result = 1.570796327f - result;
    }

    // Restore sign
    if (isNegative) {
        result = -result;
    }
    return result;
}

