static void clearMidiArmedState(bool& playArmed_, bool& recordArmed_, Icon& playIcon_, Icon& recordIcon_, bool& textClearFlag_) {
    if (!playArmed_ && !recordArmed_) return;

    playArmed_ = false;
    recordArmed_ = false;
    playIcon_.flag = true;
    playIcon_.mode = false;
    recordIcon_.flag = true;
    recordIcon_.mode = false;
    textClearFlag_ = true;
}

////////////////////////////////////////////////////////////////////////////////
/* Lpf Constants -------------------------------------------------------------*/
////////////////////////////////////////////////////////////////////////////////

const uint8_t kLpfLibrarySize                       = 2;

struct Lpf {
    bool active;
    uint16_t freq;

    float dry;
    float wet;

    float a0;
    float a1;
    float a2;
    float b1;
    float b2;

    float dataIn[3]                                 = {0.0f, 0.0f, 0.0f};
    float dataOut[3]                                = {0.0f, 0.0f, 0.0f};

    void initialize(bool active_, uint16_t freq_, float dry_, float wet_) {
        active = active_;
        freq = freq_;
        dry = dry_;
        wet = wet_;

        memset(dataIn, 0, sizeof(dataIn));
        memset(dataOut, 0, sizeof(dataOut));

        calculateFilterCoef();
    }

    void calculateFilterCoef() {
        float Q = 0.707f;
        float normFreq = (float)freq * kInvSampleRate;
        float sinOmega = sinFast(normFreq);
        float cosOmega = cosFast(normFreq);
        float alpha = sinOmega / (2.0f * Q);
        float norm = 1.0f / (1.0f + alpha);
        
        a0 = ((1.0f - cosOmega) * 0.5f) * norm;
        a1 = (1.0f - cosOmega) * norm;
        a2 = ((1.0f - cosOmega) * 0.5f) * norm;
        b1 = (-2.0f * cosOmega) * norm;
        b2 = (1.0f - alpha) * norm;
    }
};

