struct Filter {
    uint8_t num;
    bool active;
    uint8_t type;
    uint8_t slope;
    uint8_t frequency;
    uint8_t resonance;
    uint8_t drive;
    uint8_t dry;
    uint8_t wet;

    float dryFloat;
    float wetFloat;

    FilterGenTransition genTransition;
    FilterMixTransition mixTransition;

    const bool limitMix                             = true;
    const uint8_t limitMixData                      = 125;

    // standard biquad coefficients
    float b0                                        = 1.0f;
    float b1                                        = 0.0f;
    float b2                                        = 0.0f;
    float a1                                        = 0.0f;
    float a2                                        = 0.0f;

    // history (States)
    float x1                                        = 0.0f;
    float x2                                        = 0.0f;
    float y1                                        = 0.0f;
    float y2                                        = 0.0f;

    void initialize() {
        active = kInitialFilterActive;
        type = kInitialFilterType[num];
        slope = kInitialFilterSlope;
        frequency = kInitialFilterFrequency;
        resonance = kInitialFilterResonance;
        drive = kInitialFilterDrive;
        dry = kInitialFilterDry;
        wet = kInitialFilterWet;

        dryFloat = (float)dry / 100.0f;
        wetFloat = (float)wet / 100.0f;

        calculateCoef();
        cleanMemory();
    }

    void calculateCoef() {
        float freq = (float)kFilterFrequencyDataLibrary[frequency].data;
        float Q = kFilterResonanceDataLibrary[resonance].data;
        float cosw0, alpha;
        float b0_tmp, b1_tmp, b2_tmp; 
        float a0_tmp, a1_tmp, a2_tmp;
        float normFreq = freq * kInvSampleRate;
        cosw0 = cosFast(normFreq);
        float sinw0 = sinFast(normFreq);
        alpha = sinw0 / (2.0f * Q);

        switch (type) {
            case FIL_OFF:
                b0_tmp = 1.0f;
                b1_tmp = 0.0f;
                b2_tmp = 0.0f;
                a0_tmp = 1.0f;
                a1_tmp = 0.0f;
                a2_tmp = 0.0f;
                break;

            case FIL_LPF:
                b0_tmp = (1.0f - cosw0) * 0.5f;
                b1_tmp = 1.0f - cosw0;
                b2_tmp = (1.0f - cosw0) * 0.5f;
                a0_tmp = 1.0f + alpha;
                a1_tmp = -2.0f * cosw0;
                a2_tmp = 1.0f - alpha;
                break;

            case FIL_HPF:
                b0_tmp = (1.0f + cosw0) * 0.5f;
                b1_tmp = -(1.0f + cosw0);
                b2_tmp = (1.0f + cosw0) * 0.5f;
                a0_tmp = 1.0f + alpha;
                a1_tmp = -2.0f * cosw0;
                a2_tmp = 1.0f - alpha;
                break;

            case FIL_BPF:
                b0_tmp = alpha;
                b1_tmp = 0.0f;
                b2_tmp = -alpha;
                a0_tmp = 1.0f + alpha;
                a1_tmp = -2.0f * cosw0;
                a2_tmp = 1.0f - alpha;
                break;

            case FIL_BSF:  // Notch
                b0_tmp = 1.0f;
                b1_tmp = -2.0f * cosw0;
                b2_tmp = 1.0f;
                a0_tmp = 1.0f + alpha;
                a1_tmp = -2.0f * cosw0;
                a2_tmp = 1.0f - alpha;
                break;

            default:  // Pass-through
                b0_tmp = 1.0f;
                b1_tmp = 0.0f;
                b2_tmp = 0.0f;
                a0_tmp = 1.0f;
                a1_tmp = 0.0f;
                a2_tmp = 0.0f;
                break;
        }

        // Normalize
        float invA0 = 1.0f / a0_tmp;
        b0 = b0_tmp * invA0;
        b1 = b1_tmp * invA0;
        b2 = b2_tmp * invA0;
        a1 = a1_tmp * invA0;
        a2 = a2_tmp * invA0;
    }

    void cleanMemory() {
        x1 = 0.0f;
        x2 = 0.0f;
        y1 = 0.0f;
        y2 = 0.0f;
    }

    Filter(uint8_t num_) : num(num_) {}
    ~Filter() {}
};

