struct EqFilter {
    // y[n] = b0*x[n] + b1*x[n-1] + b2*x[n-2] - a1*y[n-1] - a2*y[n-2]
    float b0                                        = 1.0f;                     // Input coeff 0
    float b1                                        = 0.0f;                     // Input coeff 1
    float b2                                        = 0.0f;                     // Input coeff 2
    float a1                                        = 0.0f;                     // Output coeff 1 (Feedback)
    float a2                                        = 0.0f;                     // Output coeff 2 (Feedback)

    float x1                                        = 0.0f;                     // x[n-1]
    float x2                                        = 0.0f;                     // x[n-2]
    float y1                                        = 0.0f;                     // y[n-1]
    float y2                                        = 0.0f;                     // y[n-2]
};

typedef enum {
    EQ_ACTION_NONE                                  = 0x00,
    EQ_ACTION_UP                                    = 0x01,
    EQ_ACTION_DOWN                                  = 0x02
} EqTransitionAction;

typedef enum {
    EQ_MODE_NONE                                    = 0x00,
    EQ_MODE_ACTIVE                                  = 0x01,
} EqTransitionMode;

typedef enum {
    EQ_PHASE_NONE                                   = 0x00,
    EQ_PHASE_A                                      = 0x01,
    EQ_PHASE_B                                      = 0x02
} EqTransitionPhase;

struct EqGenTransition {
    bool active;
    EqTransitionMode mode;
    EqTransitionPhase phase;

    bool activeActive;
    bool targetActive;

    float activeDry;
    float targetDry;
    EqTransitionAction actionDry;

    float activeWet;
    float targetWet;
    EqTransitionAction actionWet;
};

struct Eq {
    bool active                                     = kInitialEqActive;

    EqGenTransition genTransition;

    uint8_t freqLowShelf;
    uint8_t gainLowShelf;
    EqFilter filterLowShelf;

    uint8_t freqHighShelf;
    uint8_t gainHighShelf;
    EqFilter filterHighShelf;

    uint8_t q                                       = kInitialEqQ;

    uint8_t freqPeak[4]                             = {kInitialEqFreqPeak[0], kInitialEqFreqPeak[1], kInitialEqFreqPeak[2], kInitialEqFreqPeak[3]};
    uint8_t gainPeak[4]                             = {kInitialEqGainPeak[0], kInitialEqGainPeak[1], kInitialEqGainPeak[2], kInitialEqGainPeak[3]};

    EqFilter filterPeak[4];

    void initialize() {
        active = kInitialEqActive;

        freqLowShelf = kInitialEqFreqLowShelf;
        gainLowShelf = kInitialEqGainLowShelf;

        freqHighShelf = kInitialEqFreqHighShelf;
        gainHighShelf = kInitialEqGainHighShelf;

        calculateCoefLowShelf();
        calculateCoefHighShelf();
        calculateCoefPeak(0);
        calculateCoefPeak(1);
        calculateCoefPeak(2);
        calculateCoefPeak(3);

        cleanMemory();
    }

    void calculateCoefLowShelf() { calculateCoef(EQ_LOWSHELF, kEqFreqDataLibrary[freqLowShelf].data, 0.707f, (float)kEqGainDataLibrary[gainLowShelf].data, filterLowShelf); }

    void calculateCoefHighShelf() { calculateCoef(EQ_HIGHSHELF, kEqFreqDataLibrary[freqHighShelf].data, 0.707f, (float)kEqGainDataLibrary[gainHighShelf].data, filterHighShelf); }

    void calculateCoefPeak(uint8_t peakNum) { calculateCoef(EQ_PEAK, kEqFreqDataLibrary[freqPeak[peakNum]].data, kEqQDataLibrary[q].data, (float)kEqGainDataLibrary[gainPeak[peakNum]].data, filterPeak[peakNum]); }

    void calculateCoef(uint8_t type, uint32_t freq, float Q, float gaindB, EqFilter& filter) {
        float A, alpha, cosw0;
        float b0_tmp, b1_tmp, b2_tmp, a0_tmp, a1_tmp, a2_tmp;
        A = powf(10.0f, gaindB * 0.025f);
        float normFreq = (float)freq * kInvSampleRate;
        cosw0 = cosFast(normFreq);
        float sinw0 = sinFast(normFreq);
        alpha = sinw0 / (2.0f * Q);

        switch (type) {
            case EQ_LOWPASS:
                b0_tmp = (1.0f - cosw0) * 0.5f;
                b1_tmp = 1.0f - cosw0;
                b2_tmp = (1.0f - cosw0) * 0.5f;
                a0_tmp = 1.0f + alpha;
                a1_tmp = -2.0f * cosw0;
                a2_tmp = 1.0f - alpha;
                break;

            case EQ_HIGHPASS:
                b0_tmp = (1.0f + cosw0) * 0.5f;
                b1_tmp = -(1.0f + cosw0);
                b2_tmp = (1.0f + cosw0) * 0.5f;
                a0_tmp = 1.0f + alpha;
                a1_tmp = -2.0f * cosw0;
                a2_tmp = 1.0f - alpha;
                break;

            case EQ_PEAK:
                b0_tmp = 1.0f + (alpha * A);
                b1_tmp = -2.0f * cosw0;
                b2_tmp = 1.0f - (alpha * A);
                a0_tmp = 1.0f + (alpha / A);
                a1_tmp = -2.0f * cosw0;
                a2_tmp = 1.0f - (alpha / A);
                break;

            case EQ_LOWSHELF: {
                float sqrtA = sqrtf(A);
                float Ap1 = A + 1.0f;
                float Am1 = A - 1.0f;
                float beta = 2.0f * sqrtA * alpha;

                b0_tmp = A * ((Ap1) - (Am1)*cosw0 + beta);
                b1_tmp = 2.0f * A * ((Am1) - (Ap1)*cosw0);
                b2_tmp = A * ((Ap1) - (Am1)*cosw0 - beta);
                a0_tmp = (Ap1) + (Am1)*cosw0 + beta;
                a1_tmp = -2.0f * ((Am1) + (Ap1)*cosw0);
                a2_tmp = (Ap1) + (Am1)*cosw0 - beta;
            } break;

            case EQ_HIGHSHELF: {
                float sqrtA = sqrtf(A);
                float Ap1 = A + 1.0f;
                float Am1 = A - 1.0f;
                float beta = 2.0f * sqrtA * alpha;

                b0_tmp = A * ((Ap1) + (Am1)*cosw0 + beta);
                b1_tmp = -2.0f * A * ((Am1) + (Ap1)*cosw0);
                b2_tmp = A * ((Ap1) + (Am1)*cosw0 - beta);
                a0_tmp = (Ap1) - (Am1)*cosw0 + beta;
                a1_tmp = 2.0f * ((Am1) - (Ap1)*cosw0);
                a2_tmp = (Ap1) - (Am1)*cosw0 - beta;
            } break;

            default:
                b0_tmp = 1.0f;
                b1_tmp = 0.0f;
                b2_tmp = 0.0f;
                a0_tmp = 1.0f;
                a1_tmp = 0.0f;
                a2_tmp = 0.0f;
                break;
        }

        float invA0 = 1.0f / a0_tmp;

        filter.b0 = b0_tmp * invA0;
        filter.b1 = b1_tmp * invA0;
        filter.b2 = b2_tmp * invA0;
        filter.a1 = a1_tmp * invA0;
        filter.a2 = a2_tmp * invA0;
    }

    void cleanMemory() {
        filterLowShelf.x1 = 0;
        filterLowShelf.x2 = 0;
        filterLowShelf.y1 = 0;
        filterLowShelf.y2 = 0;
        filterHighShelf.x1 = 0;
        filterHighShelf.x2 = 0;
        filterHighShelf.y1 = 0;
        filterHighShelf.y2 = 0;

        for (uint8_t i = 0; i < 4; i++) {
            filterPeak[i].x1 = 0;
            filterPeak[i].x2 = 0;
            filterPeak[i].y1 = 0;
            filterPeak[i].y2 = 0;
        }
    }
};

static inline float processEqBiquad(EqFilter& f, float input, bool active) {
    if (!active) return input;

    // Direct Form I
    float output = (f.b0 * input) + (f.b1 * f.x1) + (f.b2 * f.x2) - (f.a1 * f.y1) - (f.a2 * f.y2) + EQ_ANTI_DENORMAL;

    // Shift Memory
    f.x2 = f.x1;
    f.x1 = input;
    f.y2 = f.y1;
    f.y1 = output;

    return output;
}

