const uint8_t kInitialDelayWet                      = 50;

struct DelayTimeData {
    char nameLongR[11];
    float data;
};

const struct DelayTimeData kDelayTimeDataLibrary[] = {
    {"       1/8", 0.1250f},
    {"       1/6", 0.1666f},
    {"       1/4", 0.2500f},
    {"       1/3", 0.3333f},
    {"       1/2", 0.5000f},
    {"       1/1", 1.0000f}};

struct Delay {
    // --- State & Menu Parameters ---
    bool active;
    uint8_t aTime;                                  // Musical subdivision index (1/8, 1/4, etc.)
    uint8_t bLevel;                                 // Input send level index
    uint8_t cFeedback;                              // Feedback amount index
    uint8_t dDamping;                               // Feedback LPF amount (0-100) - Formerly dParam
    uint8_t eDry;                                   // Dry signal level (0-100)
    uint8_t fWet;                                   // Wet signal level (0-100)

    // --- Calculated Values ---
    float time;                                     // Subdivision multiplier
    float level;                                    // Linear input gain
    float feedback;                                 // Linear feedback gain
    float dampingAlpha;                             // Filter coefficient for damping

    // --- Buffer & Indices ---
    uint32_t lag;                                   // Calculated delay in samples
    uint32_t playInterval;                          // Read pointer
    uint32_t recordInterval;                        // Write pointer
    float lastFeedbackSample;                       // History buffer for the damping filter
    
    float* delayBuffer;                             // Pointer to external delay RAM
    const uint32_t kDelayBufferSize = kDelaySize;

    const bool limitMix = true;         
    const uint8_t limitMixData = 125;

    void initialize() { reset(); }

    void reset() {
        active = kInitialDelayActive;
        aTime = kInitialDelayTime;
        bLevel = kInitialDelayLevel;
        cFeedback = kInitialDelayFeedback;
        dDamping = kInitialDelayDamping;
        eDry = kInitialDelayDry;
        fWet = kInitialDelayWet;

        // Reset filter and pointer state to deterministic startup values.
        lastFeedbackSample = 0.0f;
        recordInterval = 0;
        playInterval = 0;
        
        // Initial sync update
        time = kDelayTimeDataLibrary[aTime].data;
        update(kInitialTempo);
    }

void update(uint16_t tempo) {
    if (tempo == 0) tempo = 1;
    
    // Update linear gains
    level = kNumberDataLibrary[bLevel].stdMultiplier;
    feedback = kNumberDataLibrary[cFeedback].stdMultiplier;

    // Formula: (seconds_per_bar * sample_rate) * subdivision_multiplier
    const float samplesPerBar = (60.0f * AUDIO_SAMPLE_RATE) / static_cast<float>(tempo);
    lag = static_cast<uint32_t>(samplesPerBar * time);
    
    // Pointer wrapping logic
    int32_t playPos = static_cast<int32_t>(recordInterval) - static_cast<int32_t>(lag);
    if (playPos < 0) playPos += static_cast<int32_t>(kDelayBufferSize);
    playInterval = static_cast<uint32_t>(playPos) % kDelayBufferSize;

    // Calculate damping coefficient (one-pole lpf)
    float freqFactor = (101.0f - static_cast<float>(dDamping)) * 0.01f;
    dampingAlpha = freqFactor * freqFactor; 
}

    void cleanMemory() {
        lastFeedbackSample = 0.0f;
    }
};

