struct ChorusDelay {
    float time;
    float depth;
    float rate;
    float mix;

    uint16_t lag;
    uint16_t playInterval;
    float chorusInterval;

    float shiftFreq;
    float shiftMax;
    float shiftMin;
    float shiftInterval;
    float shiftInc;
};

struct Chorus {
    // --- State & Menu Parameters ---
    bool active;
    uint8_t aTime;                                  // Base delay time index (10ms - 50ms)
    uint8_t bFeedback;                              // Feedback amount index (0 - 1.0)
    uint8_t cRate;                                  // LFO speed index (0.1Hz - 9Hz)
    uint8_t dDepth;                                 // LFO Depth amount (0-100)
    uint8_t eDry;                                   // Dry signal level (0-100)
    uint8_t fWet;                                   // Wet signal level (0-100)

    // --- Calculated Processing Values ---
    float time;                                     // Base delay in seconds
    float feedback;                                 // Linear feedback coefficient
    float rate;                                     // LFO frequency in Hz
    float depth;                                    // Normalized LFO depth (0.0 to 1.0)

    // --- Voice Management ---
    uint16_t recordInterval;                        // Write pointer for the global circular buffer
    const float delayCoef[2] = {1.0f, 0.75f};       // Offsets for the two voices
    ChorusDelay chorusDelay[2];                     // Internal states for each delay voice

    const bool limitMix = true;
    const uint8_t limitMixData = 125;

    void initialize() { reset(); }

    void reset() {
        active = kInitialChorusActive;
        aTime = kInitialChorusTime;
        bFeedback = kInitialChorusFeedback;
        cRate = kInitialChorusRate;
        dDepth = kInitialChorusDepth;
        eDry = kInitialChorusDry;
        fWet = kInitialChorusWet;

        update();

        // Initialize second voice at a different LFO position
        chorusDelay[1].shiftInterval = chorusDelay[1].shiftMax * 0.5f; 
        recordInterval = 0;
    }

    void update() {
        // Map menu indices to actual data
        time = kChorusTimeDataLibrary[aTime].data;
        feedback = kChorusFeedbackDataLibrary[bFeedback].data;
        rate = kChorusRateDataLibrary[cRate].data;
        depth = (float)dDepth * 0.01f;

        for (uint8_t i = 0; i < 2; i++) {
            ChorusDelay& cD = chorusDelay[i];
            float vCoef = delayCoef[i];

            cD.time = time * vCoef;
            cD.depth = depth * vCoef;
            cD.rate = rate * vCoef;
            cD.mix = 0.50f; // Each voice contributes half to the wet signal

            cD.lag = cD.time * AUDIO_SAMPLE_RATE;
            
            // Circular buffer play interval calculation
            int32_t playInterval_ = recordInterval - cD.lag;
            if (playInterval_ < 0) playInterval_ += kChorusBufferSize;
            cD.playInterval = playInterval_;

            // LFO Bounds
            cD.shiftFreq = cD.rate * 2.0f;
            cD.shiftMax = (cD.depth * (float)cD.lag) - 2.0f;
            if (cD.shiftMax < 1.0f) cD.shiftMax = 1.0f; // Safety minimum
            cD.shiftMin = -cD.shiftMax;
            
            // Increment per sample
            cD.shiftInc = ((cD.shiftMax - cD.shiftMin) * cD.shiftFreq) / AUDIO_SAMPLE_RATE;
        }
    }

    void cleanMemory() {
    }
};

