struct Phaser {
    // --- State & Menu Parameters ---
    bool active;                                    // Toggle the effect on/off
    uint8_t aStartFreq;                             // Menu index for minimum sweep frequency (0-46)
    uint8_t bEndFreq;                               // Menu index for maximum sweep frequency (0-46)
    uint8_t cRate;                                  // Menu index for LFO speed (0-25)
    uint8_t dFeedback;                              // Resonance/Feedback amount (0-100) - Updated from dParam
    uint8_t eDry;                                   // Dry signal level (0-100)
    uint8_t fWet;                                   // Wet signal level (0-100)

    // --- Calculated Processing Values ---
    uint16_t startFreq;                             // Actual start frequency in Hz fetched from library
    uint16_t endFreq;                               // Actual end frequency in Hz fetched from library
    float rate;                                     // LFO frequency in Hz
    float feedback;                                 // Linear feedback coefficient (0.0 to 0.95)
    float centerFreq;                               // Midpoint between start and end frequencies
    float depthFreq;                                // Maximum frequency deviation from center
    float lfo;                                      // Current LFO amplitude value
    float dataX;                                    // Phase accumulator for the LFO
    float dataY;                                    // Normalized LFO position (0.0 to 1.0)
    float Ts;                                       // Sampling period (1 / AUDIO_SAMPLE_RATE)

    // --- Filter History (Cascaded Stages) ---
    // Stage 1 buffers: ff[0,1], fb[0,1] | Stage 2 buffers: ff[2,3], fb[2,3]
    float ff[4];                                    // Feed-forward history
    float fb[4];                                    // Feed-back history
    float lastOutput;                               // Stores the previous output sample for the feedback loop
    float Q;                                        // Quality factor (controls bandwidth of the notches)

    // --- Constraints ---
    const bool limitMix                             = true;        
    const uint8_t limitMixData                      = 125;

    void initialize() { 
        reset(); 
    }

    void reset() {
        active = kInitialPhaserActive;

        // Load initial menu values
        aStartFreq = kInitialPhaserStartFreq;
        bEndFreq = kInitialPhaserEndFreq;
        cRate = kInitialPhaserRate;
        dFeedback = kInitialPhaserFeedback;
        eDry = kInitialPhaserDry;
        fWet = kInitialPhaserWet;

        // Fetch numerical data from libraries
        startFreq = kPhaserFreqDataLibrary[kInitialPhaserStartFreq].data;
        endFreq = kPhaserFreqDataLibrary[kInitialPhaserEndFreq].data;
        rate = kPhaserRateDataLibrary[kInitialPhaserRate].data;

        // Initialize LFO and Timing
        Ts = 1.0f / AUDIO_SAMPLE_RATE;
        dataX = 0.0f;
        dataY = 0.0f;
        lfo = 0.0f;
        Q = 0.5f;
        lastOutput = 0.0f;

        // Clear filter history to prevent audio pops
        for (int i = 0; i < 4; i++) {
            ff[i] = 0.0f;
            fb[i] = 0.0f;
        }

        update();
    }

    void update() {
        // Recalculate sweep range based on menu selections
        centerFreq = (float)startFreq + (((float)endFreq - (float)startFreq) / 2.0f);
        depthFreq = ((float)endFreq - centerFreq) * 0.9f;
        
        // Map 0-100 feedback to a safe linear range (0.0 to 0.95)
        feedback = (float)dFeedback * 0.0095f;
    }

    void cleanMemory() {
        for (int i = 0; i < 4; i++) {
            ff[i] = 0.0f;
            fb[i] = 0.0f;
        }
        lastOutput = 0.0f;
    }
};

