struct Overdrive {
    // --- State & Menu Parameters ---
    bool active;                                    // Toggle the effect on/off
    uint8_t aGain;                                  // Menu index for input drive gain (0-24)
    uint8_t bThreshold;                             // Menu index for clipping threshold (0-24)
    uint8_t cTone;                                  // Menu index for post-filter frequency (0-46)
    uint8_t dDriveColor;                            // Pre-distortion low-cut amount (0-100) - Formerly dParam
    uint8_t eDry;                                   // Dry signal level (0-100)
    uint8_t fWet;                                   // Wet signal level (0-100)

    // --- Calculated Processing Values ---
    float gaindB;                                   // Actual gain in dB from library
    float thresholddB;                              // Actual threshold in dB from library
    float gain;                                     // Linear gain multiplier
    float threshold;                                // Linear threshold/ceiling value
    float tone;                                     // Post-filter cutoff frequency in Hz
    float preFilterAlpha;                           // Smoothing coefficient for the Pre-Emphasis filter

    // --- Biquad Filter Coefficients (Post-Distortion) ---
    float a0, a1, a2, b1, b2;                       // Coefficients for the tone-shaping filter

    // --- Filter State Buffers ---
    float lp_x1, lp_x2;                             // Low-pass input history (z^-1, z^-2)
    float lp_y1, lp_y2;                             // Low-pass output history (z^-1, z^-2)
    float hp_z1;                                    // One-pole High-Pass state for Drive Color

    // --- Hardcoded Constraints ---
    const bool limitMix = true;
    const uint8_t limitMixData = 125;

    Overdrive() {
        cleanMemory();
        gain = 1.0f;
        threshold = 1.0f;
        tone = 1000.0f;
        preFilterAlpha = 1.0f;
    }

    void initialize() {
        reset();
    }

    void reset() {
        active = kInitialOverdriveActive;
        aGain = kInitialOverdriveGain;
        bThreshold = kInitialOverdriveThreshold;
        cTone = kInitialOverdriveTone;
        dDriveColor = kInitialOverdriveDriveColor;
        eDry = kInitialOverdriveDry;
        fWet = kInitialOverdriveWet;

        update();
        cleanMemory();
    }

    void update() {
        // Map menu indices to actual data from libraries
        gaindB = kOverdriveGainDataLibrary[aGain].data;
        thresholddB = kOverdriveThresholdDataLibrary[bThreshold].data;
        tone = kOverdriveToneDataLibrary[cTone].data;

        // Convert dB to linear multipliers
        gain = powf(10.0f, gaindB / 20.0f);
        threshold = powf(10.0f, thresholddB / 20.0f);

        // Calculate Pre-filter Alpha (Drive Color)
        float colorFactor = (float)dDriveColor * 0.008f;
        preFilterAlpha = 1.0f - colorFactor;
        if (preFilterAlpha < 0.1f) preFilterAlpha = 0.1f;

        calculateFilterCoef();
    }

    void calculateFilterCoef() {
        if (tone > (AUDIO_SAMPLE_RATE * 0.49f)) tone = AUDIO_SAMPLE_RATE * 0.49f;
        if (tone < 20.0f) tone = 20.0f;

        float Q = 0.707f;
        float K = tanf(M_PI * tone / (float)AUDIO_SAMPLE_RATE);
        float norm = 1.0f / (1.0f + K / Q + K * K);

        a0 = K * K * norm;
        a1 = 2.0f * a0;
        a2 = a0;
        b1 = 2.0f * (K * K - 1.0f) * norm;
        b2 = (1.0f - K / Q + K * K) * norm;
    }

    void cleanMemory() {
        lp_x1 = lp_x2 = lp_y1 = lp_y2 = 0.0f;
        hp_z1 = 0.0f;
    }
};

