struct Distortion {
    // --- State & Menu Parameters ---
    bool active;                                    // Toggle the effect on/off
    uint8_t aGain;                                  // Menu index for input drive gain (0-24)
    uint8_t bThreshold;                             // Menu index for clipping threshold (0-24)
    uint8_t cTone;                                  // Menu index for filter cutoff frequency (0-46)
    uint8_t dAsym;                                  // Asymmetry/Bias amount (0-100) - Formerly dParam
    uint8_t eDry;                                   // Dry signal level (0-100)
    uint8_t fWet;                                   // Wet signal level (0-100)

    // --- Calculated Processing Values ---
    float gaindB;                                   // Actual gain in dB fetched from library
    float thresholddB;                              // Actual threshold in dB fetched from library
    float gain;                                     // Linear gain multiplier
    float threshold;                                // Linear threshold/ceiling value
    float tone;                                     // Filter cutoff frequency in Hz
    float bias;                                     // Calculated DC offset for asymmetric clipping

    // --- Biquad Filter Coefficients ---
    float a0, a1, a2, b1, b2;                       // Filter coefficients (Standard Direct Form)

    // --- Filter State Buffers ---
    float x1, x2;                                   // Input history (z^-1, z^-2)
    float y1, y2;                                   // Output history (z^-1, z^-2)

    // --- Hardcoded Constraints ---
    const bool limitMix                             = true;
    const uint8_t limitMixData                      = 125;

    Distortion() {
        cleanMemory();

        gain = 1.0f;
        threshold = 1.0f;
        tone = 1000.0f;
        bias = 0.0f;
        a0 = 1.0f; a1 = 0.0f; a2 = 0.0f;
        b1 = 0.0f; b2 = 0.0f;
    }

    void initialize() {
        reset();
    }

    void reset() {
        active = kInitialDistortionActive;
        aGain = kInitialDistortionGain;
        bThreshold = kInitialDistortionThreshold;
        cTone = kInitialDistortionTone;
        dAsym = kInitialDistortionAsym;
        eDry = kInitialDistortionDry;
        fWet = kInitialDistortionWet;

        update();                                   // Map menu indices to real values
        cleanMemory();                              // Clear filter history
    }

    void update() {
        // Fetch values from the provided data libraries
        gaindB = kDistortionGainDataLibrary[aGain].data;
        thresholddB = kDistortionThresholdDataLibrary[bThreshold].data;
        tone = kDistortionToneDataLibrary[cTone].data;

        // Convert dB to linear values
        gain = powf(10.0f, gaindB / 20.0f);
        threshold = powf(10.0f, thresholddB / 20.0f);
        
        // Calculate Bias for Asymmetry (Maps 0-100 to 0.0-0.5)
        bias = (float)dAsym * 0.005f;

        calculateFilterCoef();
    }

    void calculateFilterCoef() {
        // Safety bounds for frequency
        if (tone > (AUDIO_SAMPLE_RATE * 0.49f)) tone = AUDIO_SAMPLE_RATE * 0.49f;
        if (tone < 20.0f) tone = 20.0f;

        float Q = 0.707f; // Standard Butterworth-ish response
        float K = tanf(M_PI * tone / (float)AUDIO_SAMPLE_RATE);
        float norm = 1.0f / (1.0f + K / Q + K * K);

        a0 = K * K * norm;
        a1 = 2.0f * a0;
        a2 = a0;
        b1 = 2.0f * (K * K - 1.0f) * norm;
        b2 = (1.0f - K / Q + K * K) * norm;
    }

    void cleanMemory() {
        x1 = x2 = 0.0f;
        y1 = y2 = 0.0f;
    }
};

