typedef enum {
    BIT_CLIP                                        = 0x00,
    BIT_FOLD                                        = 0x01,
} BitcrusherMode;

struct Bitcrusher {
    // --- State & Menu Parameters ---
    bool active;                                    // Toggle the effect on/off
    uint8_t aResolution;                            // Menu index for bit resolution (0-23)
    uint8_t bSampleRate;                            // Menu index for sample rate reduction (0-23)
    uint8_t cThreshold;                             // Menu index for threshold/gain (0-24)
    uint8_t dSmooth;                                // Smoothing/Post-filter amount (0-100)
    uint8_t eDry;                                   // Dry signal level (0-100)
    uint8_t fWet;                                   // Wet signal level (0-100)

    // --- Calculated Processing Values ---
    uint8_t resolution;                             // Actual bit depth value derived from library
    uint8_t sampleRate;                             // Actual downsampling factor derived from library
    int8_t threshold;                               // Actual threshold in dB derived from library
    BitcrusherMode mode;                            // Distortion mode: BIT_CLIP (Hard) or BIT_FOLD (Wavefolding)

    // --- Internal State Variables ---
    uint16_t sampleCounter;                         // Tracks samples for the Sample & Hold (Downsampling)
    uint16_t sampleCounterMax;                      // Target count for downsampling cadence
    uint32_t resModifier;                           // Bitmask used for bit-depth reduction logic

    float limitMultiplier;                          // Pre-calculated gain based on threshold
    float limitPos;                                 // Positive ceiling for clipping/folding
    float limitNeg;                                 // Negative floor for clipping/folding
    float sampleData;                               // Stores the last "held" sample for downsampling
    
    // --- New Smoothing/Filter Variables ---
    float lastOutput;                               // Previous filtered sample for the One-Pole LP filter
    float smoothAlpha;                              // Calculated smoothing coefficient (derived from dParam)

    // --- Hardcoded Constraints ---
    const bool limitMix                             = true;
    const uint8_t limitMixData                      = 125;


    void initialize() { 
        reset(); 
    }

     void reset() {
        active = kInitialBitcrusherActive;

        // Initialize menu parameters
        aResolution = kInitialBitcrusherResolution;
        bSampleRate = kInitialBitcrusherSampleRate;
        cThreshold = kInitialBitcrusherThreshold;
        dSmooth = kInitialBitcrusherSmooth;
        eDry = kInitialBitcrusherDry;
        fWet = kInitialBitcrusherWet;

        mode = BIT_FOLD;                   

        // Fetch actual values from data libraries
        resolution = kBitcrusherResolutionDataLibrary[kInitialBitcrusherResolution].data;
        sampleRate = kBitcrusherSampleRateDataLibrary[kInitialBitcrusherSampleRate].data;
        threshold = kBitcrusherThresholdDataLibrary[kInitialBitcrusherThreshold].data;

        // Reset internal buffers
        sampleCounter = 0;
        sampleCounterMax = sampleRate;
        sampleData = 0.0f;
        lastOutput = 0.0f;

        update();
    }

    void update() {
        sampleCounterMax = sampleRate;

        // 1. Generate the Bit Mask
        resModifier = 0;
        for (uint8_t i = 0; i < resolution; i++) {
            resModifier <<= 1;
            resModifier += 1;
        }
        for (uint8_t j = 0; j < (24 - resolution); j++) {
            resModifier <<= 1;
        }
        resModifier += 0xFF000000;

        // 2. Update Distortion Limits
        limitMultiplier = powf(10.0f, (float)threshold / 20.0f);
        limitPos = limitMultiplier;
        limitNeg = -limitPos;

        // 3. Update Smoothing Coefficient (dSmooth)
        float freqFactor = (101.0f - (float)dSmooth) * 0.01f;
        smoothAlpha = freqFactor * freqFactor; 
    }

    void cleanMemory() {}
};

